using System;using System.IO;using System.Text;using System.Runtime.Serialization.Json;using GlassBoard;
class ControlCenterTests {
    static int checks;
    static void Check(bool result,string message){checks++;if(!result)throw new Exception(message);}
    static T Read<T>(string text){using(var s=new MemoryStream(Encoding.UTF8.GetBytes(text)))return (T)new DataContractJsonSerializer(typeof(T)).ReadObject(s);}
    static T Round<T>(T value){using(var s=new MemoryStream()){var j=new DataContractJsonSerializer(typeof(T));j.WriteObject(s,value);s.Position=0;return (T)j.ReadObject(s);}}
    static int Main(){
        var defaults=Read<ControlCenterOptions>("{}");defaults.Normalize();Check(defaults.Enabled&&defaults.Motion&&defaults.Size==54&&defaults.Opacity==80,"missing fields initialize without losing explicit false");
        Check(defaults.IconSize==26&&defaults.PanelIconSize==24&&defaults.IconStyle=="switches","old configuration gains icon defaults");
        var icons=Read<ControlCenterOptions>("{\"Size\":80,\"IconSize\":48,\"PanelIconSize\":32,\"IconStyle\":\"tiles\"}");icons.Normalize();var iconSaved=Round(icons);iconSaved.Normalize();Check(iconSaved.IconSize==48&&iconSaved.PanelIconSize==32&&iconSaved.IconStyle=="tiles","separate icon sizes and style survive reload");
        Check(ControlIconRules.OrbGlyphSize(iconSaved)==48,"icon can grow past the old fixed 28-DIP limit");iconSaved.Size=36;Check(ControlIconRules.OrbGlyphSize(iconSaved)==24&&iconSaved.IconSize==48,"small orb limits drawing without losing desired icon size");iconSaved.Size=80;Check(ControlIconRules.OrbGlyphSize(iconSaved)==48,"enlarging orb restores desired glyph size");
        icons.IconSize=double.NaN;icons.PanelIconSize=double.PositiveInfinity;icons.IconStyle="unknown";icons.Normalize();Check(icons.IconSize==26&&icons.PanelIconSize==24&&icons.IconStyle=="switches","invalid sizes/styles safely default");icons.IconSize=500;icons.PanelIconSize=-100;icons.Normalize();Check(icons.IconSize==72&&icons.PanelIconSize==12,"icon size boundaries clamp independently");
        var legacy=Read<Preferences>("{\"Dock\":{\"ShowNetwork\":true},\"Apps\":[{\"Name\":\"Existing\",\"Path\":\"keep.exe\",\"Pinned\":true}],\"Widgets\":{\"Music\":true,\"Volume\":0.35,\"Playlist\":[\"song.mp3\"]}}");legacy.Normalize();
        Check(legacy.ControlCenter.Enabled&&!legacy.Dock.ShowNetwork,"legacy network shortcut migrates to control center");Check(legacy.Apps.Count==1&&legacy.Apps[0].Pinned&&legacy.Apps[0].Path=="keep.exe","migration retains pinned entries");Check(legacy.Widgets.Music&&legacy.Widgets.Playlist.Count==1&&Math.Abs(legacy.Widgets.Volume-.35)<.001,"migration retains media preferences");Check(legacy.Widgets.LyricTranslation&&legacy.Widgets.EnhancedMusic!=false,"legacy enhanced media defaults");
        legacy.ControlCenter.Enabled=false;legacy.ControlCenter.Left=-1460;legacy.ControlCenter.Top=120;legacy.ControlCenter.Size=68;legacy.ControlCenter.Opacity=42;legacy.ControlCenter.Color="#00CCFF";legacy.ControlCenter.Locked=true;legacy.ControlCenter.Topmost=true;legacy.ControlCenter.Motion=false;legacy.Dock.ShowNetwork=true;
        legacy.Widgets.EnhancedMusic=false;legacy.Widgets.ShowLyrics=false;legacy.Widgets.LyricTranslation=false;legacy.Widgets.LyricOffset=-250;legacy.Widgets.StandaloneLyrics=true;legacy.Widgets.LyricLeft=-1000;legacy.Widgets.LyricTop=800;
        var saved=Round(legacy);saved.Normalize();saved.Normalize();Check(!saved.ControlCenter.Enabled&&saved.Dock.ShowNetwork,"explicit choices survive reload and repeated migration");Check(saved.ControlCenter.Left==-1460&&saved.ControlCenter.Top==120&&saved.ControlCenter.Size==68&&saved.ControlCenter.Opacity==42,"negative-monitor position and appearance persist");Check(saved.ControlCenter.Locked&&saved.ControlCenter.Topmost&&!saved.ControlCenter.Motion,"behavior toggles persist");Check(saved.Widgets.EnhancedMusic==false&&saved.Widgets.ShowLyrics==false&&!saved.Widgets.LyricTranslation&&saved.Widgets.LyricOffset==-250,"media opt-outs and calibration persist");Check(saved.Widgets.StandaloneLyrics&&saved.Widgets.LyricLeft==-1000&&saved.Widgets.LyricTop==800,"standalone lyric layout persists");
        saved.ControlCenter.Size=double.NaN;saved.ControlCenter.Opacity=double.PositiveInfinity;saved.ControlCenter.Left=double.NaN;saved.ControlCenter.Top=double.PositiveInfinity;saved.ControlCenter.Color="bad!";saved.Widgets.LyricOffset=int.MinValue;saved.Normalize();Check(saved.ControlCenter.Size==54&&saved.ControlCenter.Opacity==80&&!saved.ControlCenter.Left.HasValue&&!saved.ControlCenter.Top.HasValue,"malformed dimensions reset safely");Check(saved.ControlCenter.Color=="#A9C9FF"&&saved.Widgets.LyricOffset==-10000,"malformed colors and extreme offset normalize");
        Console.WriteLine(checks+" migration/persistence checks PASS");return 0;
    }
}
